<script setup>
import {computed,ref,onMounted,onBeforeUnmount,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {useLearning} from '@/store.js';
import {libraryApi} from '@/services/library.js';
import {modelApi} from '@/services/models.js';
import {useModelJob} from '@/lib/useModelJob.js';
import Workspace from './Workspace.vue';
import KnowledgePicker from './KnowledgePicker.vue';
import {curriculumApi} from '@/services/curriculum.js';
import SourceReader from './SourceReader.vue';
import CaseArticle from './CaseArticle.vue';
import MathVerification from './MathVerification.vue';
import ModelResult from './ModelResult.vue';
import {Upload,Plus,RefreshCw,Download,FileText,BookOpen,ArrowLeft,Check,LoaderCircle,X} from '@/components/app/icons.js';
const route=useRoute(),router=useRouter(),store=useLearning();
const contextKey=`sczx:library-context:${store.user?.id||'anonymous'}`;
function savedContext(){try{return JSON.parse(sessionStorage.getItem(contextKey)||'null')}catch{return null}}
function rememberContext(){if(initializing||disposed)return;try{sessionStorage.setItem(contextKey,JSON.stringify({tab:tab.value,case:selectedCase.value?.id,material:material.value?.id,unit:unitId.value}))}catch{}}
const knowledge=ref([]);
const materials=ref([]),cases=ref([]),extractionJobs=ref([]),material=ref(null),selectedCase=ref(null),unitId=ref(''),selectedUnits=ref([]),tab=ref('materials'),editorTab=ref('body'),sourceTab=ref('original');
const listError=ref(''),initialLoad=ref(true),showSource=ref(false),materialMode=ref('read'),metadataOpen=ref(false),experienceSection=ref('goal'),metadataSaving=ref(false);
const experienceGroups=[{value:'goal',label:'目标与学情'},{value:'lesson',label:'课堂过程'},{value:'scope',label:'知识与适用范围'}];
const experienceFields=computed(()=>Object.fromEntries(Object.entries(labels).filter(([key])=>({goal:['goal','studentBase','difficulty','diagnosis'],lesson:['introduction','steps','questions','responses','adjustment','strategy','effectCheck'],scope:['knowledgePoints','boundary','suggestions']})[experienceSection.value].includes(key))));
const actionBusy=ref(false);
const error=ref(''),notice=ref(''),loading=ref(false),saving=ref(false),uploading=ref(false),uploadOpen=ref(false),preview=ref(false),confirmAction=ref(''),dirty=ref(false),edited=ref(null),reviewed=ref(false),unitText=ref('');
const metadata=ref({title:'',author:'',sourceUrl:'',sourceNote:'',grade:'',subject:''}),uploadFile=ref(null);
let timer,disposed=false,selection=0,materialSelection=0,initializing=true;
const uploadedMaterial=ref(null);
const uploadNotice=computed(()=>{
 if(!uploadedMaterial.value)return '';
 const item=materials.value.find(item=>item.id===uploadedMaterial.value.id)||uploadedMaterial.value;
 return ({ready:'原文件已保存，解析完成',partial:'原文件已保存，部分内容未完成解析',failed:'原文件已保存，解析失败，请重试'})[item.status]||'原文件已保存，正在解析';
});
watch(()=>[tab.value,selectedCase.value?.id,material.value?.id,unitId.value],rememberContext);
const currentUnit=computed(()=>material.value?.units.find(u=>u.id===unitId.value));
const labels={knowledgePoints:'知识点',goal:'教学目标',studentBase:'学生基础',difficulty:'学生困难',diagnosis:'诊断依据',strategy:'具体教法',effectCheck:'效果检查',introduction:'引入方法',steps:'讲解步骤',questions:'教师提问',responses:'可能回应',adjustment:'回应后的调整',boundary:'适用边界',suggestions:'模型建议'};
const listField=value=>Array.isArray(value)?value:typeof value==='string'&&value.trim()?[value]:[];
const arrays=new Set(['knowledgePoints','steps','questions','responses','suggestions']);
const referenceOptions=computed(()=>[{value:'content',label:'案例正文'},...Object.entries(labels).filter(([key])=>key!=='suggestions').flatMap(([key,label])=>arrays.has(key)?listField(edited.value?.experience?.[key]).map((_,index)=>({value:`${key}.${index}`,label:`${label} ${index+1}`})):[{value:key,label}])]);
const knowledgeCandidates=computed(()=>{const text=[edited.value?.title,edited.value?.experience?.goal,edited.value?.experience?.difficulty,...listField(edited.value?.experience?.knowledgePoints)].filter(Boolean).join(' ').normalize('NFKC').toLowerCase();return knowledge.value.map(p=>({...p,matchedNames:[p.name,...(p.aliases||[])].filter(n=>text.includes(n.normalize('NFKC').toLowerCase())),source:'name'})).filter(p=>p.matchedNames.length)});
const stateName=s=>({queued:'排队中',running:'识别中',ready:'已就绪',processing:'处理中',partial:'部分完成',failed:'失败',empty:'待处理',published:'已发布',withdrawn:'已撤回',draft:'草稿'}[s]||s);
const {job,busy,error:jobError,open}=useModelJob(async value=>{if(value.status==='succeeded'&&value.result?.caseId){await loadLists();await selectCase(value.result.caseId);notice.value='已生成独立草稿，请对照原文修订。'}});
async function loadLists(){listError.value='';try{[materials.value,cases.value,extractionJobs.value]=await Promise.all([libraryApi.materials(),libraryApi.cases(),libraryApi.jobs()])}catch(e){listError.value=e.message}finally{initialLoad.value=false}}
function applyCase(item){selectedCase.value=item;const data=item.draft||item.published;if(data){const {reviewed:checked,updatedAt,...body}=data;edited.value=structuredClone(body);edited.value.provenance||={kind:'unknown',author:'',evidence:'',authorization:'unknown',authorizationEvidence:''};reviewed.value=!!checked}else edited.value=null;dirty.value=false}
async function selectCase(id){if(dirty.value&&!(await saveCase()))return;const version=++selection;error.value='';loading.value=true;try{const item=await libraryApi.case(id);if(version!==selection||disposed)return;applyCase(item);tab.value='cases';const ref=item.draft?.references?.[0]||item.published?.references?.[0];await router.replace({query:{...route.query,case:id,job:undefined,...(ref?{material:ref.materialId,unit:ref.unitId}:{})}});if(ref)await selectMaterial(ref.materialId,ref.unitId,false)}catch(e){if(version===selection){selectedCase.value=null;edited.value=null;error.value=e.message}}finally{if(version===selection)loading.value=false}}
async function selectMaterial(id,unit=null,setRoute=true){const version=++materialSelection;error.value='';try{const item=await libraryApi.material(id);if(version!==materialSelection||disposed)return;if(material.value?.id!==id)materialMode.value='read';material.value=item;unitId.value=(item.units.some(u=>u.id===unit)?unit:null)||item.units[0]?.id||'';if(setRoute)await router.replace({query:{...route.query,material:id,unit:unitId.value}})}catch(e){if(version===materialSelection){material.value=null;unitId.value='';error.value=e.message}}}
watch(()=>[currentUnit.value?.id,currentUnit.value?.text],([id,text],[oldId,oldText]=[])=>{if(id!==oldId||unitText.value===(oldText||''))unitText.value=text||''});
function changed(){dirty.value=true;reviewed.value=false}
async function saveCase(){if(!selectedCase.value?.draft||!edited.value)return true;const id=selectedCase.value.id;saving.value=true;error.value='';try{const result=await libraryApi.save(id,edited.value);if(selectedCase.value?.id===id)applyCase(result);notice.value='草稿已保存';await loadLists();return true}catch(e){error.value=e.message;return false}finally{saving.value=false}}
async function action(name){if(actionBusy.value||!selectedCase.value)return;const id=selectedCase.value.id;actionBusy.value=true;error.value='';try{if(name==='verify'){if(!(await saveCase()))return;const result=await libraryApi.action(id,'verify');if(selectedCase.value?.id===id)applyCase(result);notice.value='列出的数学表达已重新核对';return}if(name==='review'){if(!(await saveCase()))return;await libraryApi.action(id,'review');if(selectedCase.value?.id===id){reviewed.value=true;selectedCase.value.draft.reviewed=true;}notice.value='已记录人工核对';return}if(name==='publish'&&!(await saveCase()))return;const result=await libraryApi.action(id,name);if(selectedCase.value?.id===id)applyCase(result);confirmAction.value='';await loadLists();notice.value=name==='publish'?'案例已发布':name==='withdraw'?'已停止新检索，历史版本保留':'已创建修订草稿'}catch(e){error.value=e.message}finally{actionBusy.value=false}}
async function upload(){if(!uploadFile.value){error.value='请选择原文件。';return}uploading.value=true;error.value='';try{const form=new FormData();form.append('file',uploadFile.value);for(const[k,v]of Object.entries(metadata.value))form.append(k,v);const item=await libraryApi.upload(form);uploadedMaterial.value=item;notice.value='';uploadOpen.value=false;await loadLists();tab.value='materials';await selectMaterial(item.id)}catch(e){error.value=e.message}finally{uploading.value=false}}
async function saveUnit(){try{await libraryApi.saveUnit(unitId.value,unitText.value);await selectMaterial(material.value.id,unitId.value,false);notice.value='识别文本已保存'}catch(e){error.value=e.message}}
async function extract(){if(!selectedUnits.value.length){error.value='请选择要整理的原文位置。';return}try{const response=await libraryApi.extract(selectedUnits.value);await router.replace({query:{...route.query,job:response.jobId}});await open(await modelApi.detail(response.jobId));notice.value='正在整理选中的原文，离开后任务继续执行'}catch(e){error.value=e.message}}
async function create(){try{const item=await libraryApi.newCase(selectedUnits.value);await loadLists();await selectCase(item.id)}catch(e){error.value=e.message}}
async function retry(id){try{const retried=await modelApi.retry(id);if(job.value?.id===id)await open(retried);await refresh()}catch(e){error.value=e.message}}
async function refresh(){await loadLists();if(material.value){const item=await libraryApi.material(material.value.id);if(material.value?.id===item.id)Object.assign(material.value,{units:item.units,status:item.status,ready:item.ready,total:item.total,error:item.error,parseStatus:item.parseStatus});if(!unitId.value&&item.units[0])unitId.value=item.units[0].id}}
async function saveMeta(){if(metadataSaving.value)return;metadataSaving.value=true;error.value='';try{await libraryApi.saveMaterial(material.value.id,material.value);await loadLists();notice.value='材料信息已保存';metadataOpen.value=false}catch(e){error.value=e.message}finally{metadataSaving.value=false}}
function fieldValue(key){const value=edited.value?.experience?.[key];return Array.isArray(value)?value.join('\n'):value||''}
function setField(key,value){edited.value.experience||={};edited.value.experience[key]=arrays.has(key)?value.split('\n').filter(Boolean):value;changed()}
async function originalVersion(id){const item=await libraryApi.case(selectedCase.value.id);if(id===item.published?.versionId){versionPreview.value=item.published;preview.value=true;return}const version=await modelApi.caseDetail(item.id,id);versionPreview.value=version;preview.value=true}
const versionPreview=ref(null);
async function addReferences(){try{edited.value.references||=[];for(const id of selectedUnits.value){const unit=await libraryApi.unit(id);edited.value.references.push({unitId:id,materialId:unit.materialId,materialTitle:unit.materialTitle,label:unit.label,quote:unit.text.slice(0,1000),author:unit.metadata.author,source:unit.metadata.sourceNote,sourceUrl:unit.metadata.sourceUrl})}changed()}catch(e){error.value=e.message}}
onMounted(async()=>{
 try{knowledge.value=await curriculumApi.knowledge()}catch(e){error.value=e.message}
 const requested={case:route.query.case,material:route.query.material,unit:route.query.unit,job:route.query.job};
 const remembered=Object.values(requested).some(Boolean)?null:savedContext();
 await loadLists();
 const caseId=requested.case||(remembered?.tab==='cases'&&cases.value.some(item=>item.id===remembered.case)?remembered.case:null);
 const materialId=requested.material||(!caseId&&materials.value.some(item=>item.id===remembered?.material)?remembered.material:null);
 if(caseId)await selectCase(String(caseId));
 if(materialId)await selectMaterial(String(materialId),String(requested.unit||remembered?.unit||'')||null);
 else if(!material.value&&materials.value[0])await selectMaterial(materials.value[0].id);
 if(!caseId&&remembered?.tab==='cases')tab.value='cases';
 if(requested.job)await inspectJob({id:String(requested.job)});
 initializing=false;rememberContext();
 timer=setInterval(()=>refresh().catch(e=>error.value=e.message),3000);
});
watch(()=>[route.query.case,route.query.material,route.query.unit,route.query.job],async([caseId,materialId,unit,jobId])=>{if(initializing||disposed)return;if(caseId&&caseId!==selectedCase.value?.id)await selectCase(String(caseId));if(materialId&&(materialId!==material.value?.id||(unit&&unit!==unitId.value)))await selectMaterial(String(materialId),unit?String(unit):null,false);if(jobId&&jobId!==job.value?.id)await inspectJob({id:String(jobId)})});
async function inspectJob(item){tab.value='materials';try{await router.replace({query:{...route.query,job:item.id}});await open(await modelApi.detail(item.id));const first=job.value?.input?.units?.[0];if(first&&job.value.status!=='succeeded')await selectMaterial(first.materialId,first.id);materialMode.value='organize'}catch(e){error.value=e.message}}
onBeforeUnmount(()=>{disposed=true;selection++;clearInterval(timer)});
</script>
<template>
  <PageHeading title="资料与案例"><AppButton variant="outline" @click="loadLists"><RefreshCw :size="16" />刷新</AppButton><AppButton @click="uploadOpen=true"><Upload :size="16" />上传材料</AppButton></PageHeading>
  <AppAlert type="error" v-if="error||listError||jobError" role="alert" class="form-error">{{ error||listError||jobError }}</AppAlert><AppAlert type="success" v-if="initialLoad||loading" role="status" class="library-notice">读取中…</AppAlert><AppAlert type="success" v-if="notice||uploadNotice" role="status" class="library-notice">{{ notice||uploadNotice }}</AppAlert>
  <div class="library-layout">
    <ElAside width="100%" class="library-rail"><AppTabs v-model="tab" :items="[{value:'materials',label:'材料'},{value:'cases',label:'案例'}]" /><div class="library-list" v-if="tab==='materials'"><p v-if="!materials.length" class="ai-empty">上传一份材料开始整理</p><AppButton :variant="(material?.id===item.id)?'selected':'ghost'" data-layout="row" type="button" v-for="item in materials" :key="item.id" :class="{active:material?.id===item.id}" @click="selectMaterial(item.id)"><FileText :size="17" /><span><strong>{{ item.title }}</strong><small>{{ stateName(item.status) }} 　 {{ item.ready }}/{{ item.total }}</small></span></AppButton></div><div class="library-list" v-else><AppButton variant="ghost" @click="create"><Plus :size="16" />新建案例</AppButton><AppButton :variant="(selectedCase?.id===item.id)?'selected':'ghost'" data-layout="row" type="button" v-for="item in cases" :key="item.id" :disabled="saving||actionBusy" :class="{active:selectedCase?.id===item.id}" @click="selectCase(item.id)"><BookOpen :size="17" /><span><strong>{{ item.draft?.title||item.published?.title }}</strong><small>{{ item.draft?'编辑中 　 ':'' }}{{ stateName(item.status) }}</small></span></AppButton></div><AppDisclosure class="library-job-history"><template #title>整理任务</template><AppButton variant="ghost" data-layout="row" type="button" v-for="item in extractionJobs" :key="item.id" @click="inspectJob(item)"><strong>{{ item.summary||'教学经验提取' }}</strong><span>{{ item.step }}</span><time>{{ new Date(item.createdAt).toLocaleString('zh-CN') }}</time></AppButton></AppDisclosure></ElAside>
    <div class="library-main"><div :class="['ops-material-workspace',{'with-source':tab==='cases'&&showSource}]">
      <Surface data-ui="card" v-if="tab==='materials'||showSource" class="library-original">
        <template v-if="material"><div class="library-pane-heading"><h2>{{ material.title }}</h2><ElLink :underline="false" v-if="!material.units.length" :href="`/api/files/${material.fileId}`" target="_blank" rel="noopener"><Download :size="16" />原文件</ElLink><Status :tone="material.status==='ready'?'green':'amber'">{{ stateName(material.status) }}</Status></div>
          <div class="admin-material-mode"><AppTabs v-model="materialMode" :items="[{value:'read',label:'阅读材料'},{value:'organize',label:'整理成案例'}]"/><AppButton variant="ghost" @click="metadataOpen=true">编辑信息</AppButton></div>
          <AppAlert type="error" v-if="material.error" role="alert" class="form-error">{{ material.error }}</AppAlert><AppButton v-if="material.parseStatus==='failed'" variant="outline" @click="retry(material.parseJobId)">重试未完成解析</AppButton>
          <ElSpace wrap :size="12" v-if="materialMode==='read'&&material.units.length" class="library-source-tools"><AppSelect v-model="unitId" label="选择原文位置" @update:model-value="id=>router.replace({query:{...route.query,material:material.id,unit:id}})" :options="material.units.map(u=>({value:u.id,label:u.label+(u.status==='ready'?'':' 　 '+stateName(u.status))}))" /><AppTabs v-model="sourceTab" :items="[{value:'original',label:'原文'},{value:'text',label:'识别文本'}]" /></ElSpace>
          <AppAlert type="error" v-if="currentUnit?.status==='failed'" role="alert" class="form-error">{{ currentUnit.error }}</AppAlert><AppButton v-if="currentUnit?.status==='failed'" variant="outline" @click="retry(currentUnit.jobId)">重试本页识别</AppButton>
          <SourceReader compact v-if="materialMode==='read'&&unitId&&sourceTab==='original'" :unit-id="unitId" :key="currentUnit?.text" />
          <template v-if="materialMode==='read'&&currentUnit&&sourceTab==='text'"><label class="field-label" for="unit-text">核对识别文本</label><Textarea id="unit-text" v-model="unitText" class="library-unit-text" /><AppAlert type="error" v-if="currentUnit.details?.uncertainties?.length" class="form-error">{{ currentUnit.details.uncertainties.join('；') }}</AppAlert><p v-for="warning in currentUnit.details?.warnings" :key="warning" class="model-model-name">{{ warning }}</p><AppButton variant="outline" @click="saveUnit">保存识别文本</AppButton></template>
          <Surface data-ui="card" v-if="materialMode==='organize'" class="library-selection admin-material-selection"><div class="admin-selection-heading"><h3>选择内容</h3><span>{{ selectedUnits.length }} / 8<InfoTip label="整理范围限制">每次最多8处、合计24000字；长材料可分批整理为多个草稿。</InfoTip></span></div><AppCheckbox v-for="unit in material.units" :key="unit.id" v-model="selectedUnits" :value="unit.id" :disabled="!unit.text.trim()">{{ unit.label }}<span>{{ stateName(unit.status) }}</span></AppCheckbox><ElSpace wrap :size="12" class="library-actions"><AppButton :disabled="busy||!selectedUnits.length" @click="extract"><LoaderCircle v-if="busy" :size="16" class="model-spinner" />{{ busy?'正在整理…':'提取为新案例' }}</AppButton><AppButton variant="ghost" @click="create">手动整理</AppButton><AppButton v-if="selectedUnits.length" variant="ghost" @click="selectedUnits=[]">清空选择</AppButton></ElSpace><ModelResult :job="job" :busy="busy" @retry="retry(job.id)" /></Surface>
        </template><AppEmpty v-else class="empty-state"><FileText :size="28" /><h3>选择或上传材料</h3><AppButton variant="outline" @click="uploadOpen=true">上传材料</AppButton></AppEmpty>
      </Surface>
      <Surface data-ui="card" class="library-editor" v-if="tab==='cases'&&selectedCase&&edited&&!loading"><div class="library-pane-heading"><h2>{{ selectedCase.draft?'案例草稿':selectedCase.status==='withdrawn'?'已撤回案例':'已发布案例' }}</h2><Status :tone="selectedCase.draft?(reviewed?'green':'amber'):selectedCase.status==='published'?'green':'amber'">{{ selectedCase.draft?(reviewed?'已核对':'待核对'):'v'+selectedCase.published.version }}</Status></div><ElSpace wrap :size="12" class="library-actions"><AppButton variant="ghost" @click="showSource=!showSource">{{showSource?'收起来源':'对照原文'}}</AppButton><template v-if="selectedCase.draft"><AppButton :disabled="saving||actionBusy" variant="outline" @click="saveCase">{{ saving?'保存中…':dirty?'保存修改':'保存草稿' }}</AppButton><AppButton variant="ghost" @click="versionPreview=null;preview=true">预览</AppButton><AppButton :disabled="!reviewed||dirty||actionBusy" @click="confirmAction='publish'">发布案例</AppButton></template><AppButton v-else @click="action('revise')">创建修订</AppButton><AppButton v-if="selectedCase.status==='published'" variant="ghost" @click="confirmAction='withdraw'">撤回</AppButton></ElSpace>
        <fieldset v-if="selectedCase.draft" :disabled="saving||actionBusy" class="library-draft-fields"><AppTabs v-model="editorTab" :items="[{value:'body',label:'正文'},{value:'experience',label:'教学经验'},{value:'sources',label:'出处'},{value:'knowledge',label:'知识关联'}]" /><div v-if="editorTab==='body'" class="library-fields"><label for="case-title">案例标题</label><Input id="case-title" v-model="edited.title" @update:model-value="changed" /><label for="case-content">案例正文</label><Textarea id="case-content" v-model="edited.content" class="library-case-text" @update:model-value="changed" /><AppCheckbox :checked="reviewed" :disabled="dirty||saving||actionBusy" @change="$event.target.checked&&action('review')">已对照原文核对内容<InfoTip label="人工核对">先保存草稿，再确认核对；修改内容后需要重新核对。</InfoTip></AppCheckbox></div><div v-else-if="editorTab==='experience'" class="library-fields"><AppTabs v-model="experienceSection" :items="experienceGroups"/><template v-if="experienceSection==='lesson'"><AppDisclosure class="library-math-editor"><template #title>编辑核对表达式</template><div v-for="(claim,index) in edited.experience?.mathClaims||[]" :key="index"><Input v-model="claim.left" :aria-label="`第${index+1}组左表达式`" @update:model-value="changed" /><span>=</span><Input v-model="claim.right" :aria-label="`第${index+1}组右表达式`" @update:model-value="changed" /><AppButton variant="ghost" size="icon-sm" :aria-label="`删除第${index+1}组表达式`" @click="edited.experience.mathClaims.splice(index,1);changed()"><X :size="15" /></AppButton></div><AppButton variant="ghost" :disabled="(edited.experience?.mathClaims?.length||0)>=12" @click="edited.experience||={};edited.experience.mathClaims||=[];edited.experience.mathClaims.push({left:'',right:''});changed()"><Plus :size="15" />添加表达式</AppButton></AppDisclosure><MathVerification :value="edited.verification" /><AppButton v-if="edited.experience?.mathClaims?.length" variant="outline" @click="action('verify')">重新核对列出的等式</AppButton></template><label v-for="(label,key) in experienceFields" :key="key">{{ label }}<Textarea :model-value="fieldValue(key)" @update:model-value="setField(key,$event)" /></label></div><div v-else-if="editorTab==='knowledge'" class="library-fields"><KnowledgePicker :model-value="edited.knowledgeIds||[]" :points="knowledge" :suggestions="knowledgeCandidates" @update:model-value="edited.knowledgeIds=$event;changed()"/></div><div v-else class="library-fields"><label>来源类型<AppSelect v-model="edited.provenance.kind" label="经验来源类型" :options="[{value:'unknown',label:'来源未核验'},{value:'teacher',label:'教师提供并确认'},{value:'public',label:'公开材料整理'},{value:'team',label:'团队自编'},{value:'ai_candidate',label:'AI辅助候选'}]" @update:model-value="changed"/></label><label>来源作者<Input v-model="edited.provenance.author" @update:model-value="changed"/></label><label>来源或教师确认依据<Textarea v-model="edited.provenance.evidence" @update:model-value="changed"/></label><label>使用许可<AppSelect v-model="edited.provenance.authorization" label="使用许可" :options="[{value:'unknown',label:'待确认'},{value:'internal',label:'已确认内部教学使用'},{value:'redistribution_confirmed',label:'已确认可再分发'}]" @update:model-value="changed"/></label><label>授权依据<Textarea v-model="edited.provenance.authorizationEvidence" @update:model-value="changed"/></label><AppButton variant="outline" :disabled="!selectedUnits.length" @click="addReferences">关联左侧所选原文</AppButton><label v-for="(label,key) in {source:'来源说明',author:'作者或机构',grade:'适用年级',subject:'学科'}" :key="key">{{ label }}<Input v-model="edited[key]" @update:model-value="changed" /></label><Surface data-ui="card" v-for="(ref,index) in edited.references" :key="index" class="case-reference-edit"><ElLink :underline="false" :href="`/#/source?unit=${ref.unitId}`" target="_blank" rel="noopener">{{ ref.materialTitle }} 　 {{ ref.label }}</ElLink><AppSelect :model-value="ref.field||'content'" label="引用对应内容" :options="referenceOptions" @update:model-value="ref.field=$event;changed()" /><label>原文摘录<Textarea v-model="ref.quote" @update:model-value="changed" /></label></Surface><p v-if="!edited.references?.length" class="ai-empty">选择左侧原文位置，新建关联原文的案例。</p></div></fieldset>
        <CaseArticle v-else :value="edited" /><AppDisclosure v-if="selectedCase.versions.length" class="library-version-list"><template #title>已发布版本</template><AppButton variant="ghost" data-layout="row" type="button" v-for="v in selectedCase.versions" :key="v.id" @click="originalVersion(v.id)">版本 {{ v.number }}<span>{{ new Date(v.publishedAt).toLocaleString('zh-CN') }}</span></AppButton></AppDisclosure>
      </Surface><AppEmpty v-else-if="tab==='cases'" class="empty-state library-editor-empty"><BookOpen :size="28" /><h3>还没有选中案例</h3><AppButton variant="outline" @click="create">新建案例</AppButton></AppEmpty>
    </div></div>
  </div>
  <AppDialog v-model:open="metadataOpen" title="材料信息"><ElForm v-if="material" class="library-upload-form" @submit.prevent="saveMeta"><label>标题<Input v-model="material.title"/></label><label v-for="(label,key) in {author:'作者或机构',sourceUrl:'来源链接',sourceNote:'来源说明',grade:'适用年级',subject:'学科'}" :key="key">{{label}}<Input v-model="material.metadata[key]"/></label><AppAlert type="error" v-if="error" class="form-error" role="alert">{{error}}</AppAlert><AppButton type="submit" :disabled="metadataSaving">{{metadataSaving?'保存中…':'保存信息'}}</AppButton></ElForm></AppDialog>
  <AppDialog v-model:open="uploadOpen" title="上传原始材料"><ElForm class="library-upload-form" @submit.prevent="upload"><label for="material-file">原文件<InfoTip label="文件范围">PDF、DOCX、PNG/JPEG，最多30MB；PDF最多30页，Word最多300个片段。</InfoTip></label><AppFilePicker id="material-file" accept=".pdf,.docx,.png,.jpg,.jpeg" @change="uploadFile=$event.target.files?.[0]"/><label v-for="(label,key) in {title:'材料标题',author:'作者或机构',sourceUrl:'来源链接',sourceNote:'来源说明',grade:'适用年级',subject:'学科'}" :key="key">{{ label }}<Input v-model="metadata[key]" /></label><AppAlert type="error" v-if="error" class="form-error" role="alert">{{ error }}</AppAlert><AppButton :disabled="uploading" type="submit">{{ uploading?'上传中…':'上传并解析' }}</AppButton></ElForm></AppDialog>
  <AppDialog v-model:open="preview" title="案例预览" content-class="library-preview"><h2 class="case-preview-title">{{ (versionPreview||edited)?.title }}</h2><CaseArticle :value="versionPreview||edited" /></AppDialog>
  <AppDialog :open="!!confirmAction" @update:open="!$event&&(confirmAction='')" :title="confirmAction==='publish'?'发布案例':'撤回案例'"><p>{{ confirmAction==='publish'?'发布后教师可检索和用于备课，学生指导可使用该版本。':'撤回后不再进入新检索；已发布版本及历史任务引用仍保留。' }}</p><AppAlert type="error" v-if="error" role="alert" class="form-error">{{ error }}</AppAlert><AppButton :disabled="actionBusy" @click="action(confirmAction)">{{ actionBusy ? '处理中…' : confirmAction==='publish'?'确认发布':'确认撤回' }}</AppButton></AppDialog>
</template>

<style scoped>
.case-preview-title{font-size:24px;font-weight:650;line-height:1.45;letter-spacing:-.02em;margin:4px 0 12px;}
</style>
